import { createSignal, For, onCleanup, onMount, Show, type JSX } from 'solid-js'
import fixture from '../fixtures/investigation.json'
import { LensDashboard } from './LensDashboard'
import type { InvestigationHost, SavedInvestigation } from './explore/investigation'
import type { LensThemeMode } from './runtime'
import { navigationToURL } from './runtime/url'
import { backURL, readReturnContext, returnParam, type LensReturnContext } from './runtime/returnContext'
import './styles.css'

/**
 * Save an exploration and come back to it without losing context.
 *
 * Generated by `go run ./cmd/lens-report-example --investigation`: a composed
 * "Finance overview" with one "Branch margin" report. Its drill goes region →
 * branch → host records; each level declares the report dimension its
 * selection constrains, so the position is a saveable slice of the report's
 * source. The margin is a ratio of host-computed profit and revenue.
 *
 * The story emulates the host around LensDashboard: a document/query server
 * (which can expire the first snapshot), an InvestigationHost that can fail
 * saving or adding, and a host records page that keeps its own sort and page
 * and returns to the exploration through the drill return protocol.
 */

const panelId = 'margin::panel:margin'
const explorer = 'margin::margin'
const branch = `${explorer}/by-region`
const perspective = `${branch}/composition`
const regions = `${perspective}/regions`
const investigationRegionsPath = [explorer, branch, perspective, regions]
const investigationNorthPath = [...investigationRegionsPath, `${regions}/north`]

type Levels = Record<string, unknown>
const levels = fixture.levels as Levels

function json(value: unknown, status = 200): Response {
  return new Response(JSON.stringify(value), { status, headers: { 'Content-Type': 'application/json' } })
}

/** The host's Lens endpoints. The first snapshot can be made to expire. */
function createServer(options: { expire?: boolean }) {
  let generation = 0
  const fetcher: typeof fetch = (input, init) => Promise.resolve(respond(input, init))
  const respond = (input: Parameters<typeof fetch>[0], init: Parameters<typeof fetch>[1]): Response => {
    const url = new URL(typeof input === 'string' ? input : input instanceof URL ? input.href : input.url, globalThis.location.href)
    if (url.pathname === '/demo/lens/document') {
      generation += 1
      const document = structuredClone(fixture.document)
      document.snapshotId = `investigation-${generation}`
      return json(document)
    }
    if (url.pathname === '/demo/lens/query') {
      const body = JSON.parse(typeof init?.body === 'string' ? init.body : '{}') as { snapshotId: string; path: Array<string> }
      if (options.expire && body.snapshotId === 'investigation-1') {
        return json({ error: 'snapshot_gone', message: 'The snapshot expired.' }, 410)
      }
      const key = [...body.path].reverse().find((candidate) => candidate in levels)
      if (!key) return json({ error: 'bad_request', message: 'Unknown level' }, 400)
      return json({ frames: { [`level:${key}`]: levels[key] } })
    }
    return json({ error: 'bad_request', message: `Unknown endpoint ${url.pathname}` }, 404)
  }
  return fetcher
}

interface HostOptions {
  saveable?: boolean
  failSaves?: number
  failPlaces?: number
  slow?: boolean
}

/** The host side of saving: it records every call so a story shows what happened. */
function createHost(options: HostOptions, log: (line: string) => void): InvestigationHost {
  let saves = 0
  let places = 0
  const reports = new Map<string, SavedInvestigation>()
  // Request ids are random; the log names them by first appearance so a retry
  // visibly reuses its id and the story renders the same on every run.
  const ids = new Map<string, string>()
  const idLabel = (id: string) => {
    if (!ids.has(id)) ids.set(id, `request-${ids.size + 1}`)
    return ids.get(id)!
  }
  const capabilities = fixture.source.capabilities
  return {
    capabilities: () => options.saveable === false ? { ...capabilities, save: false } : capabilities,
    async save(request) {
      saves += 1
      log(`save #${saves} ${request.intent} “${request.proposal.title}” id=${idLabel(request.id)}`)
      if (options.slow) await new Promise((resolve) => setTimeout(resolve, 60_000))
      if (saves <= (options.failSaves ?? 0)) throw new Error('Storage unavailable')
      // Idempotent by request id: a retry of the same save returns the same report.
      const existing = reports.get(request.id)
      if (existing) return existing
      const report = { reportId: `report-${reports.size + 1}`, title: request.proposal.title, href: `/demo/reports/report-${reports.size + 1}` }
      reports.set(request.id, report)
      log(`created ${report.reportId} · ${request.proposal.filters.constraints?.map((constraint) => `${constraint.dimension}=${constraint.values.join('|')}`).join(', ')}`)
      return report
    },
    destinations: {
      destinations() {
        return Promise.resolve([{ id: 'finance-overview', title: 'Finance overview', placed: 1 }, { id: 'branch-network', title: 'Branch network' }])
      },
    },
    place(request) {
      places += 1
      log(`place #${places} ${request.report.reportId} → ${request.choice.kind === 'existing' ? request.choice.destination.id : 'new dashboard'}`)
      if (places <= (options.failPlaces ?? 0)) return Promise.reject(new Error('Dashboard draft locked'))
      log(`opened draft of ${request.choice.kind === 'existing' ? request.choice.destination.title : 'a new dashboard'}`)
      return Promise.resolve()
    },
  }
}

/** A host's operational records page. It owns sort, page and scroll; Lens hands them back. */
function HostRecords(props: { href: string; onBack: (href: string) => void }): JSX.Element {
  const url = new URL(props.href, globalThis.location.href)
  const context: LensReturnContext | undefined = readReturnContext(url)
  const restored = (() => {
    try { return context?.host ? JSON.parse(context.host) as { sort: 'asc' | 'desc'; page: number } : undefined } catch { return undefined }
  })()
  const [sort, setSort] = createSignal<'asc' | 'desc'>(restored?.sort ?? 'desc')
  const [page, setPage] = createSignal(restored?.page ?? 1)
  const rows = () => {
    const all = Array.from({ length: 9 }, (_, index) => ({ id: `INV-${1040 + index}`, amount: 1200 + ((index * 7919) % 5000) }))
    all.sort((left, right) => sort() === 'asc' ? left.amount - right.amount : right.amount - left.amount)
    return all.slice((page() - 1) * 3, page() * 3)
  }
  let back: HTMLAnchorElement | undefined
  onMount(() => back?.focus())
  const backHref = () => context ? backURL(context, url.pathname, JSON.stringify({ sort: sort(), page: page() })) : undefined
  return (
    <section aria-label="Host records" class="lens-panel story-host-records" data-testid="host-records">
      <Show when={context} fallback={<p>Opened without a Lens context: no way back is shown.</p>}>
        {(value) => (
          <nav class="story-host-back">
            <a
              data-testid="host-back"
              href={backHref()}
              onClick={(event) => { event.preventDefault(); props.onBack(backHref()!) }}
              ref={(element) => { back = element }}
            >
              ← Back to {value().title}{value().trail?.length ? ` › ${value().trail!.join(' › ')}` : ''}
            </a>
          </nav>
        )}
      </Show>
      <h3>Invoices · branch {url.searchParams.get('branch')}</h3>
      <div class="story-host-toolbar">
        <button data-testid="host-sort" onClick={() => setSort(sort() === 'asc' ? 'desc' : 'asc')} type="button">Amount {sort() === 'asc' ? '↑' : '↓'}</button>
        <button data-testid="host-next" disabled={page() >= 3} onClick={() => setPage(page() + 1)} type="button">Next page</button>
        <span data-testid="host-page">Page {page()} of 3</span>
      </div>
      <table>
        <tbody>
          <For each={rows()}>{(row) => <tr><td>{row.id}</td><td>{row.amount.toLocaleString('en-US')}</td></tr>}</For>
        </tbody>
      </table>
    </section>
  )
}

interface ScenarioProps extends HostOptions {
  theme: LensThemeMode
  path?: Array<string>
  expire?: boolean
  /** Opens a state on mount so the story shows it at rest. */
  open?: 'level' | 'save' | 'save-failed' | 'add-failed'
  width?: string
}

/**
 * Clicks the control once it is enabled, the way a person would: only after the
 * surface it sits on has painted. A dialog moves focus to its first field in an
 * animation frame after it mounts; clicking before that frame would let the
 * story's end state depend on whether the frame or the click won (a slow CI
 * runner delays the frame, the click disables the field, and focus lands on it
 * only after the save failed). Two frames guarantee the dialog's own frame ran.
 */
function clickWhenReady(selector: string, attempts = 120): Promise<void> {
  return new Promise((resolve) => {
    const tick = (left: number) => {
      const element = globalThis.document.querySelector<HTMLElement>(selector)
      if (element && !(element as HTMLButtonElement).disabled) {
        requestAnimationFrame(() => requestAnimationFrame(() => {
          element.click()
          resolve()
        }))
        return
      }
      if (left > 0) setTimeout(() => tick(left - 1), 50)
      else resolve()
    }
    tick(attempts)
  })
}

function settled(label: string, attempts = 200): Promise<void> {
  return new Promise((resolve) => {
    const tick = (left: number) => {
      const trail = globalThis.document.querySelector('.lens-trail-current')
      const busy = globalThis.document.querySelector('.lens-explore-level [aria-busy="true"]')
      if ((trail?.textContent === label && !busy) || left === 0) {
        // Two frames after the level drew, so the card opens on a layout that has stopped moving.
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
        return
      }
      setTimeout(() => tick(left - 1), 50)
    }
    tick(attempts)
  })
}

async function openState(open: ScenarioProps['open']) {
  if (!open) return
  await settled('North')
  await clickWhenReady('.lens-trail-current')
  if (open === 'level') return
  await clickWhenReady('[data-testid="drill-save"]')
  if (open === 'save') return
  await clickWhenReady('[data-testid="investigation-publish-add"]')
  if (open === 'save-failed') return
  await clickWhenReady('[data-testid="report-destination-picker"] input[type="radio"][value="finance-overview"]')
  await clickWhenReady('[data-testid="report-destination-confirm"]')
  await new Promise((resolve) => setTimeout(resolve, 50))
  await clickWhenReady('[data-testid="report-destination-picker"] .lens-report-picker-actions .lens-context-action:not(.lens-report-primary)')
}

function Scenario(props: ScenarioProps): JSX.Element {
  const [log, setLog] = createSignal<Array<string>>([])
  const append = (line: string) => setLog((lines) => [...lines, line])
  const host = createHost(props, append)
  const fetcher = createServer({ expire: props.expire })
  const [records, setRecords] = createSignal<string>()
  // Every mount is a fresh page load: the runtime reads its position from the URL only.
  const [mount, setMount] = createSignal(0)
  // A pasted link (a new tab) keeps its own position; otherwise the story pins one.
  if (!new URL(globalThis.location.href).searchParams.has('path')) {
    globalThis.history.replaceState(null, '', navigationToURL({ panelId, path: props.path ?? [], ...(props.path?.length ? { perspectiveId: perspective } : {}) }, new URL(globalThis.location.href)))
  }

  // A link that leaves Lens for the host's records is followed by the host page.
  const follow = (event: MouseEvent) => {
    const anchor = (event.target as Element | null)?.closest?.('a[href]') as HTMLAnchorElement | null
    if (!anchor || !new URL(anchor.href).searchParams.has(returnParam)) return
    event.preventDefault()
    append(`opened ${new URL(anchor.href).pathname}${new URL(anchor.href).search.slice(0, 32)}…`)
    setRecords(anchor.href)
  }
  onMount(() => {
    globalThis.document.addEventListener('click', follow, true)
    void openState(props.open)
  })
  onCleanup(() => globalThis.document.removeEventListener('click', follow, true))

  return (
    <div class="lens-root" data-theme={props.theme === 'dark' ? 'dark' : 'light'} style={props.width ? { width: props.width } : undefined}>
      <Show
        when={records()}
        fallback={(
          <Show keyed when={mount() + 1}>
            <LensDashboard
              fetcher={fetcher}
              filterToday={{ year: 2026, month: 7, day: 22 }}
              investigation={host}
              locale="en"
              returnContext
              src="/demo/lens/document"
              theme={props.theme}
            />
          </Show>
        )}
      >
        {(href) => (
          <HostRecords
            href={href()}
            onBack={(back) => {
              append(`back to ${back.length > 48 ? `${back.slice(0, 48)}…` : back}`)
              globalThis.history.replaceState(null, '', back)
              setRecords(undefined)
              setMount((value) => value + 1)
            }}
          />
        )}
      </Show>
      <ol aria-label="Host calls" class="story-host-log" data-testid="host-log">
        <For each={log()}>{(line) => <li>{line}</li>}</For>
      </ol>
    </div>
  )
}

